## 01 / 完全背包
```cpp
int ZCbag(int V, std::vector<int> &w, std::vector<int> &v) {//    O(nV)
    int n = w.size();
    std::vector<int> f(V + 1);

    for (int i = 0; i < n; i++) {
        for (int j = V; j >= w[i]; j--) {//01
        //for (int j = w[i]; j <= V; j++) {//完全
            f[j] = std::max(f[j], f[j - w[i]] + v[i]);
        }
    }

    return f[V];
}
```
